WITH valid_orders AS (SELECT *, DATE_FORMAT(order_date, 'MMM yyyy') AS order_date_label FROM orders WHERE shipping_fee BETWEEN 30 AND 39), orders_stats AS (SELECT CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, MAX(order_date) AS last_order_date FROM valid_orders GROUP BY CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT order_cohort, last_order_date FROM orders_stats ORDER BY last_order_date DESC;
